// Generates contract/ts/src/generated/** from contract/schema/**.
//
// The generated files are committed, so consumers need no generation step.
// test/generated.test.ts calls generate() and fails when the committed files
// differ from a fresh generation, so a schema change without regeneration
// fails CI.
//
// Usage: npm run generate -w @chapter/capture-contract

import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { compile, type JSONSchema } from "json-schema-to-typescript";
import { format, resolveConfig } from "prettier";

const here = dirname(fileURLToPath(import.meta.url));
export const packageDir = resolve(here, "..");
export const schemaSourceDir = resolve(packageDir, "..", "schema");
export const generatedDir = join(packageDir, "src", "generated");

/** Schema files in contract/schema, by short name. Order is the export order. */
export const SCHEMA_FILES = {
  "capture-record": "capture-record.schema.json",
  "capture-model": "capture-model.schema.json",
  "field-controls": "field-controls.schema.json",
  manifest: "manifest.schema.json",
  "sketch-measurements": "sketch-measurements.schema.json",
  "walkthrough-log": "walkthrough-log.schema.json",
  verdict: "verdict.schema.json",
} as const;

export type SchemaName = keyof typeof SCHEMA_FILES;

const CONDITIONAL_KEYWORDS = ["if", "then", "else", "not"] as const;

type Json = null | boolean | number | string | Json[] | { [key: string]: Json };

function readJson(path: string): { [key: string]: Json } {
  return JSON.parse(readFileSync(path, "utf8")) as { [key: string]: Json };
}

function isObject(value: Json | undefined): value is { [key: string]: Json } {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * TypeScript names for $defs whose key would make a confusing type name.
 * `object` would shadow the global `Object` type.
 */
const TYPE_NAMES: Partial<Record<SchemaName, Record<string, string>>> = {
  "capture-model": { object: "CaptureObject" },
  "sketch-measurements": {
    room: "SketchRoom",
    wall: "SketchWall",
    opening: "SketchOpening",
    diagonal: "SketchDiagonal",
    length: "SketchLength",
  },
  "walkthrough-log": {
    room: "WalkthroughRoom",
    opening: "WalkthroughOpening",
    tap: "WalkthroughTap",
    frame: "WalkthroughFrame",
    length: "WalkthroughLength",
  },
};

/**
 * Returns the copy of a schema that json-schema-to-typescript reads. The Ajv
 * validators always use the schema unchanged.
 *
 * 1. Drops the validation-only conditionals if/then/else/not, and allOf
 *    members left empty by that. TypeScript cannot express them, and the
 *    generator turns them into duplicated intersections. Every conditional in
 *    contract/schema only constrains properties declared next to it
 *    (additionalProperties is false everywhere), so no property, name or type
 *    changes.
 * 2. Drops a description that sits next to a $ref. Otherwise the generator
 *    inlines the target or emits numbered copies (CaptureRef1, Vec31), so the
 *    exported type names would depend on schema order.
 */
export function prepareForTypes(node: Json): Json {
  if (Array.isArray(node)) {
    return node.map(prepareForTypes);
  }
  if (!isObject(node)) {
    return node;
  }
  const hasRef = typeof node["$ref"] === "string";
  const out: { [key: string]: Json } = {};
  for (const [key, value] of Object.entries(node)) {
    if ((CONDITIONAL_KEYWORDS as readonly string[]).includes(key)) {
      continue;
    }
    if (hasRef && key === "description") {
      continue;
    }
    out[key] = prepareForTypes(value);
  }
  const allOf = out["allOf"];
  if (Array.isArray(allOf)) {
    const kept = allOf.filter((member) => !(isObject(member) && Object.keys(member).length === 0));
    if (kept.length === 0) {
      delete out["allOf"];
    } else {
      out["allOf"] = kept;
    }
  }
  return out;
}

function withTypeNames(name: SchemaName, schema: Json): Json {
  const names = TYPE_NAMES[name];
  if (!names || !isObject(schema) || !isObject(schema["$defs"])) {
    return schema;
  }
  const defs: { [key: string]: Json } = { ...schema["$defs"] };
  for (const [def, title] of Object.entries(names)) {
    const entry = defs[def];
    if (!isObject(entry)) {
      throw new Error(`${SCHEMA_FILES[name]} has no $defs/${def} to name ${title}`);
    }
    defs[def] = { ...entry, title };
  }
  return { ...schema, $defs: defs };
}

function camel(name: string): string {
  return name.replace(/-([a-z])/g, (_match, letter: string) => letter.toUpperCase());
}

function banner(source: string): string {
  return [
    "/*",
    ` * Generated by contract/ts/scripts/generate.ts from ${source}.`,
    " * Do not edit by hand. Run: npm run generate -w @chapter/capture-contract",
    " */",
  ].join("\n");
}

async function pretty(fileName: string, source: string): Promise<string> {
  const filepath = join(generatedDir, fileName);
  const config = (await resolveConfig(filepath)) ?? {};
  return format(source, { ...config, filepath });
}

function enumOf(schema: { [key: string]: Json }, def: string): string[] {
  const defs = schema["$defs"];
  const entry = isObject(defs) ? defs[def] : undefined;
  const values = isObject(entry) ? entry["enum"] : undefined;
  if (!Array.isArray(values) || !values.every((value) => typeof value === "string")) {
    throw new Error(`manifest.schema.json $defs/${def} has no string enum`);
  }
  return values as string[];
}

/**
 * Roles a manifest of the newest schemaVersion must not list: the `not.enum` of the role in the
 * root `allOf` member whose `if` names that version.
 */
function retiredRolesOf(schema: { [key: string]: Json }): string[] {
  const properties = schema["properties"];
  const version = isObject(properties) ? properties["schemaVersion"] : undefined;
  const versions = isObject(version) ? version["enum"] : undefined;
  const newest = Array.isArray(versions) ? versions[versions.length - 1] : undefined;
  const members = schema["allOf"];
  for (const member of Array.isArray(members) ? members : []) {
    if (!isObject(member) || !isObject(member["if"]) || !isObject(member["then"])) {
      continue;
    }
    const condition = member["if"]["properties"];
    const named = isObject(condition) ? condition["schemaVersion"] : undefined;
    if (!isObject(named) || named["const"] !== newest) {
      continue;
    }
    let node: Json | undefined = member["then"];
    for (const key of ["properties", "files", "items", "properties", "role", "not", "enum"]) {
      node = isObject(node) ? node[key] : undefined;
    }
    if (Array.isArray(node) && node.every((value) => typeof value === "string")) {
      return node as string[];
    }
  }
  throw new Error(`manifest.schema.json has no retired-role rule for ${String(newest)}`);
}

/** Generates every file of src/generated, keyed by file name. Writes nothing. */
export async function generate(): Promise<Map<string, string>> {
  const files = new Map<string, string>();
  const schemas = new Map<SchemaName, { [key: string]: Json }>();

  for (const [name, file] of Object.entries(SCHEMA_FILES) as [SchemaName, string][]) {
    const schema = readJson(join(schemaSourceDir, file));
    schemas.set(name, schema);
    const types = await compile(
      withTypeNames(name, prepareForTypes(schema)) as JSONSchema,
      String(schema["title"]),
      {
        bannerComment: "",
        cwd: schemaSourceDir,
        declareExternallyReferenced: true,
        format: false,
        additionalProperties: false,
        unreachableDefinitions: false,
      },
    );
    const fileName = `${name}.ts`;
    files.set(fileName, await pretty(fileName, `${banner(`contract/schema/${file}`)}\n\n${types}`));
  }

  const schemaLines = [banner("contract/schema/*.schema.json"), ""];
  for (const [name, schema] of schemas) {
    schemaLines.push(
      `export const ${camel(name)}Schema: Record<string, unknown> = ${JSON.stringify(schema)};`,
      "",
    );
  }
  files.set("schemas.ts", await pretty("schemas.ts", schemaLines.join("\n")));

  const manifest = schemas.get("manifest");
  if (!manifest) {
    throw new Error("manifest schema missing");
  }
  const layout = readJson(join(schemaSourceDir, "layout.json"));
  const constants = [
    banner("contract/schema/layout.json and contract/schema/manifest.schema.json"),
    "",
    "/** Folder layout of an intake package (contract/schema/layout.json). */",
    `export const LAYOUT = ${JSON.stringify(layout)} as const;`,
    "",
    "/** Every manifest file role (manifest.schema.json $defs/role), in schema order. */",
    `export const ROLES = ${JSON.stringify(enumOf(manifest, "role"))} as const;`,
    "",
    "/** Roles of visit-wide files (manifest.schema.json $defs/visitRole). Every other role belongs to one capture. */",
    `export const VISIT_ROLES = ${JSON.stringify(enumOf(manifest, "visitRole"))} as const;`,
    "",
    "/** Retired roles: valid in manifest 1.0.0 only, never written by a current app (manifest.schema.json allOf). */",
    `export const RETIRED_ROLES = ${JSON.stringify(retiredRolesOf(manifest))} as const;`,
    "",
  ];
  files.set("constants.ts", await pretty("constants.ts", constants.join("\n")));

  return files;
}

/** Writes the generated files and removes stale ones. */
export async function writeGenerated(): Promise<string[]> {
  const files = await generate();
  mkdirSync(generatedDir, { recursive: true });
  for (const existing of readdirSync(generatedDir)) {
    if (!files.has(existing)) {
      rmSync(join(generatedDir, existing));
    }
  }
  for (const [fileName, content] of files) {
    writeFileSync(join(generatedDir, fileName), content);
  }
  return [...files.keys()];
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const written = await writeGenerated();
  console.log(`Wrote ${written.length} files to ${generatedDir}`);
}
